// ---------------------------------------------------------------------------
// Repo-local two-table registry resolution (S3 rulings 1, 9)
// ---------------------------------------------------------------------------

export interface ResolvedModel {
  slug: string;
  backend: string;
  /** Which adapter handles this backend (threaded from backends.json's `family`; s3-rulings.md ruling 1 two-table config). */
  family: BackendFamily;
  modelId: string;
  /** null for SaaS backends (codex/claude) whose CLIs connect directly; a real endpoint is required for the "pi" family (enforced below). */
  baseUrl: string | null;
  apiKeyEnv: string | null;
  secretsFile: string | null;
  availableOn: string[];
  /** Per-family effort/reasoning CLI mapping, threaded from backends.json's `effort_mapping` (WK-0122). Absent = this backend does not support effort — the mapping IS the capability declaration, replacing the old `supportsEffort` boolean. */
  effortMapping?: EffortMapping;
  /** §7.13 context-budget gate input (tokens). Defaults to DEFAULT_CONTEXT_WINDOW; floor at MIN_CONTEXT_WINDOW. */
  contextWindow: number;
  requestParams?: Record<string, unknown>;
}

/**
 * Default context window (tokens) when backends.json omits serving.context_window.
 * 128k matches the native capacity of every current dispatch-target model
 * (DeepSeek, Qwen3, Gemma, GLM). Operators override when their deployment
 * serves at a smaller window (Ollama num_ctx, vLLM max_model_len).
 */
export const DEFAULT_CONTEXT_WINDOW = 131072;

/**
 * Minimum context window (tokens). Pi's compaction reserve is 16384
 * (compaction.js:76 in Pi 0.85.1); below 2x reserve Pi enters an infinite
 * compaction loop (shouldCompact threshold goes negative).
 * Verified against Pi 0.85.1 source: compaction.js:160-163.
 */
export const MIN_CONTEXT_WINDOW = 32768;

/**
 * Resolve `--model <slug> --backend <name>` (both required — s3-rulings.md
 * ruling 1) against `wiki/.dispatch/models.json` + `backends.json`. An
 * `available_on` mismatch between the two tables is a warning, never a
 * refusal (ruling 1) — the tables are independently operator-edited, so a
 * backend the models table hasn't caught up to listing must not block a
 * dispatch. Absent tables resolve to empty maps (repo-config.ts's valid-empty
 * semantics), so a missing `wiki/.dispatch/` dir surfaces here as an ordinary
 * `MODEL_NOT_FOUND` with an empty `available` list rather than a distinct
 * error path.
 */
export async function resolveModelFromConfig(
  dir: string,
  slug: string,
  backend: string,
): Promise<DispatchResult<ResolvedModel>> {
  const modelsResult = await loadModelsTable(dir);
  if (!modelsResult.ok) return modelsResult;

  const backendsResult = await loadBackendsTable(dir);
  if (!backendsResult.ok) return backendsResult;

  const modelEntry = modelsResult.data[slug];
  if (!modelEntry) {
    return fail('MODEL_NOT_FOUND', `Model slug not found in models.json: ${slug}`, {
      slug,
      available: Object.keys(modelsResult.data),
    });
  }

  const backendEntry = backendsResult.data[backend];
  if (!backendEntry) {
    return fail('MODEL_NOT_FOUND', `Backend not found in backends.json: ${backend}`, {
      backend,
      available: Object.keys(backendsResult.data),
    });
  }

  if (!modelEntry.available_on.includes(backend)) {
    console.warn(
      `Warning: model "${slug}" does not list backend "${backend}" in available_on (has: ${modelEntry.available_on.join(', ') || 'none'}); proceeding (s3-rulings.md ruling 1).`,
    );
  }

  // A null base_url means the family's own CLI reaches its SaaS provider
  // directly (codex/claude — repo-config.ts's BackendEntry doc comment).
  // Only the "pi" pipeline requires a real endpoint (buildPiBaseUrl in
  // pipeline.ts, which calls `new URL()` on it) — refuse here, loudly,
  // rather than let a null base_url reach that call unchecked. codex/claude
  // backends resolve through with `baseUrl: null` (T33 family-aware pipeline).
  if (backendEntry.base_url === null && backendEntry.family === 'pi') {
    return fail(
      'BAD_RECORD',
      `Backend "${backend}" in backends.json has no base_url configured; the "pi" family requires one.`,
      { backend },
    );
  }

  const contextWindow = backendEntry.serving?.context_window ?? DEFAULT_CONTEXT_WINDOW;
  if (contextWindow < MIN_CONTEXT_WINDOW) {
    return fail(
      'BAD_RECORD',
      `Backend "${backend}" serving.context_window is ${contextWindow}, below minimum ${MIN_CONTEXT_WINDOW}. Pi requires at least 2× its compaction reserve (16384) to function.`,
      { contextWindow, minimum: MIN_CONTEXT_WINDOW },
    );
  }

  return ok({
    slug,
    backend,
    family: backendEntry.family,
    modelId: modelEntry.model_id,
    baseUrl: backendEntry.base_url,
    apiKeyEnv: backendEntry.api_key_env,
    secretsFile: backendEntry.secrets_file,
    availableOn: modelEntry.available_on,
    effortMapping: backendEntry.effort_mapping,
    contextWindow,
    ...(backendEntry.request_params ? { requestParams: backendEntry.request_params } : {}),
  });
}

/**
 * Resolve a model + backend by HO mode (WK-0070) — the config-driven default
 * path taken when `--model`/`--backend` are both omitted from a dispatch
 * call. Collects every (slug, backend) candidate where the model's `use_for`
 * (models.json) includes `mode` and the backend is both listed in that
 * model's `available_on` and present in backends.json. Exactly one candidate
 * delegates to `resolveModelFromConfig` for the full resolution (base_url
 * checks, context window, etc.); zero or multiple candidates refuse loudly
 * rather than guessing.
 */
export async function resolveModelByMode(
  dir: string,
  mode: string,
): Promise<DispatchResult<ResolvedModel>> {
  const modelsResult = await loadModelsTable(dir);
  if (!modelsResult.ok) return modelsResult;

  const backendsResult = await loadBackendsTable(dir);
  if (!backendsResult.ok) return backendsResult;

  const candidates: { slug: string; backend: string }[] = [];
  for (const [slug, entry] of Object.entries(modelsResult.data)) {
    if (!entry.use_for?.includes(mode)) continue;
    for (const backend of entry.available_on) {
      if (backendsResult.data[backend]) {
        candidates.push({ slug, backend });
      }
    }
  }

  if (candidates.length === 0) {
    return fail('NO_MODEL_DEFAULT', `No model in models.json has use_for matching mode '${mode}'. Provide --model and --backend explicitly, or add use_for to a models.json entry.`, {
      mode,
      availableModels: Object.keys(modelsResult.data),
    });
  }

  if (candidates.length > 1) {
    return fail(
      'AMBIGUOUS_MODEL_DEFAULT',
      `Multiple models/backends match use_for '${mode}': ${candidates.map((c) => `${c.slug}/${c.backend}`).join(', ')}. Provide --model and --backend explicitly.`,
      { mode, candidates },
    );
  }

  const candidate = candidates[0];
  return resolveModelFromConfig(dir, candidate.slug, candidate.backend);
}

/**
 * Resolve a model when only --model is given (no --backend). Infers the
 * backend from available_on: exactly one entry → use it; multiple → refuse
 * with AMBIGUOUS_BACKEND (WK-0070 partial specification).
 */
export async function resolveModelInferBackend(
  dir: string,
  slug: string,
): Promise<DispatchResult<ResolvedModel>> {
  const modelsResult = await loadModelsTable(dir);
  if (!modelsResult.ok) return modelsResult;

  const modelEntry = modelsResult.data[slug];
  if (!modelEntry) {
    return fail('MODEL_NOT_FOUND', `Model slug not found in models.json: ${slug}`, {
      slug,
      available: Object.keys(modelsResult.data),
    });
  }

  if (modelEntry.available_on.length !== 1) {
    return fail(
      'AMBIGUOUS_BACKEND',
      `Model "${slug}" is available on ${modelEntry.available_on.length} backends: ${modelEntry.available_on.join(', ')}. Specify --backend explicitly.`,
      { slug, backends: modelEntry.available_on },
    );
  }

  return resolveModelFromConfig(dir, slug, modelEntry.available_on[0]);
}

