    lines.push(
      `_FP_VERSION=$(curl -s -m 2 ${shQuote(`${rootUrl}/api/version`)} 2>/dev/null | grep -o '"version":"[^"]*"' | cut -d'"' -f4 || echo "unknown")`,
    );
